const MEV_K = 1.160452e10; // kelvin per MeV

/**
 * Neutron fraction through the first minutes: X' = λpn (1 − X) − λnp X with Mukhanov's massless-electron weak rates plus
 * free decay, clocked by the neutrino temperature (∝ 1/a) with a smooth e± annihilation that heats photons by (11/4)^{1/3}.
 * Nuclei form when η⁻¹ exp(−Δ_D/T) = 1 (PDG). Returns the curve [{t, T (MeV), X, Xeq}] and the summary numbers.
 */
function bbn(eta10, Nnu, tauN = 879.4) {
  const Q = 1.293, Mpl = 1.221e22, hbar = 6.582e-22, DD = 2.224;
  const S = (Tn) => 1 / (1 + Math.exp((Math.log(Tn) - Math.log(0.12)) / 0.45)), rr = (Tn) => 1 + 0.401 * S(Tn);
  const geff = (Tn) => (2 + 3.5 * (1 - S(Tn))) * rr(Tn) ** 4 + 1.75 * Nnu;
  const H = (Tn) => (1.66 * Math.sqrt(geff(Tn)) * Tn * Tn) / Mpl / hbar;
  const lnp = (T) => { const x = Q / T; return ((255 / tauN) * (12 + 6 * x + x * x)) / x ** 5; };
  const Tnuc = DD / Math.log(1 / (eta10 * 1e-10));
  let Tn = 12, t = 1 / (2 * H(12)), X = 1 / (1 + Math.exp(Q / Tn)), nuc = null, fr = null;
  const out = [], dl = -0.004;
  while (Tn > 0.012) {
    const T = Tn * rr(Tn), lam = lnp(T) + 1 / tauN, lpn = lnp(T) * Math.exp(-Q / T), dt = -dl / H(Tn);
    X = (X + dt * lpn) / (1 + dt * (lpn + lam)); t += dt; Tn *= Math.exp(dl); // implicit step: stable for the fast early rates
    const Tg = Tn * rr(Tn);
    out.push({ t, T: Tg, X, Xeq: 1 / (1 + Math.exp(Q / Tg)) });
    if (!fr && lnp(Tg) < H(Tn)) fr = { t, T: Tg, X };
    if (!nuc && Tg < Tnuc) nuc = { t, T: Tg, X, Yp: 2 * X };
  }
  return { out, fr, nuc, Tnuc };
}
/** Planck intensity in MJy/sr at wavenumber σ (cm⁻¹) and temperature T (K). */
function planckMJy(sig, T) { const h = 6.62607015e-34, c = 2.99792458e8, k = 1.380649e-23, nu = 100 * c * sig; return ((2 * h * nu ** 3) / (c * c) / Math.expm1((h * nu) / (k * T))) * 1e20; }

