/** Periodic-table slot of element Z: [row, column]; rows 9 and 10 are the lanthanides and actinides. */
function ptSlot(Z) {
  if (Z === 1) return [1, 1]; if (Z === 2) return [1, 18];
  if (Z <= 4) return [2, Z - 2]; if (Z <= 10) return [2, Z + 8]; if (Z <= 12) return [3, Z - 10]; if (Z <= 18) return [3, Z];
  if (Z <= 36) return [4, Z - 18]; if (Z <= 54) return [5, Z - 36]; if (Z <= 56) return [6, Z - 54]; if (Z <= 71) return [9, Z - 54];
  if (Z <= 86) return [6, Z - 68]; if (Z <= 88) return [7, Z - 86]; return [10, Z - 86];
}
/** B−V → effective temperature (Ballesteros 2012). */
const teffBV = (bv) => 4600 * (1 / (0.92 * bv + 1.7) + 1 / (0.92 * bv + 0.62));

// ── 2.6 constants (SI) ───────────────────────────────────────────────────────────────────────────────────────────────
const GN = 6.674e-11, ME = 5.9724e24, MM = 7.346e22, RE = 6.371e6, CE = 0.3308 * ME * RE * RE, A0 = 3.844e8, ECC = 0.0549;
const W0 = (2 * Math.PI) / (23.9345 * 3600), YR = 3.15576e7, SIDYR_H = 365.256 * 24;
const MU = (ME * MM) / (ME + MM), LORB = (a) => MU * Math.sqrt(GN * (ME + MM) * a * (1 - ECC * ECC)), LTOT = CE * W0 + LORB(A0);
/** Solar day in hours for a sidereal spin ω. */
const solarDayH = (w) => { const sid = (2 * Math.PI) / w / 3600; return sid / (1 - sid / SIDYR_H); };

